{"command":"cat > src/cli.js <<'EOF'
const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/
const lines = require_input().split('\n')
if (lines[lines.length - 1] === '') lines.pop()

function require_input() {
  return process.stdin.isTTY ? '' : readAll()
}
function readAll() {
  return require('node:fs').readFileSync(0, 'utf8')
}

let cands = null
const ballots = []
let seenBallot = false
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t[0] === '#') continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (w[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    seenBallot = true
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!COUNT.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const alive = new Set(cands)
const history = []
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const counts = new Map([...alive].map((c) => [c, 0n]))
  let active = 0n
  let total = 0n
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => alive.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const order = [...alive].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    return d > 0n ? 1 : d < 0n ? -1 : a < b ? -1 : a > b ? 1 : 0
  })
  let line = `round ${roundNo}: ` + order.map((c) => `${c}=${counts.get(c)}`).join(' ')
  line += ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const w = order.find((c) => counts.get(c) * 2n > active)
  if (w !== undefined) {
    winner = w
    break
  }
  let min = null
  for (const c of alive) if (min === null || counts.get(c) < min) min = counts.get(c)
  let tied = [...alive].filter((c) => counts.get(c) === min)
  for (;;) {
    if (tied.length === 1) break
    let r = history.findIndex((h) => tied.some((c) => h.get(c) !== h.get(tied[0])))
    if (r < 0) break
    let m = null
    for (const c of tied) if (m === null || history[r].get(c) < m) m = history[r].get(c)
    tied = tied.filter((c) => history[r].get(c) === m)
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  alive.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'tally') process.stdout.write(`rounds ${roundNo}\n${end}\n`)
else process.stdout.write(out.join('\n') + '\n' + end + '\n')
EOF
